template:
% 参数由系统自动注入；圆柱斜二测图，上下底面椭圆，OO'中心轴，半径OA,O'A'，母线AA'
% 视觉归一化：最长外接边缩放到6个坐标单位，线宽与虚线样式不缩放
\pgfmathsetmacro{\ellipseY}{\radius * \xscale}
\pgfmathsetmacro{\xmin}{-\radius}
\pgfmathsetmacro{\xmax}{\radius}
\pgfmathsetmacro{\ymin}{0}
\pgfmathsetmacro{\ymax}{\height + \ellipseY}
\pgfmathsetmacro{\figscale}{6 / max(\xmax-\xmin, \ymax-\ymin)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
    \coordinate (O)  at (0,0);
    \coordinate (Op) at (0,\height);
    \coordinate (A)  at (\radius, 0);
    \coordinate (Ap) at (\radius, \height);
    % 上底面椭圆（全部实线）
    \draw[blue, thick] (Op) ellipse (\radius and \ellipseY);
    % 下底面椭圆：前半实线，后半虚线
    \draw[blue, thick] (O) ellipse (\radius and \ellipseY);
    \draw[blue, thick, dashed] (O) arc[start angle=180, end angle=360, x radius=\radius, y radius=\ellipseY];
    % 两条竖直母线
    \draw[black, thick] (-\radius, 0) -- (-\radius, \height);
    \draw[black, thick] (\radius, 0) -- (\radius, \height);
    % 中心对称轴OO'
    \ifnum\showaxis>0
        \draw[green!60!black, dashed, thick] (O)--(Op);
    \fi
    % 半径OA, O'A' 橙色
    \draw[orange, thick] (O)--(A);
    \draw[orange, thick] (Op)--(Ap);
    % 母线AA' 橙色虚线
    \draw[orange, thick, dashed] (A)--(Ap);
    % 标签
    \ifnum\showlabels>0
        \node[below left] at (O) {$O$};
        \node[above left] at (Op) {$O'$};
        \node[below right] at (A) {$A$};
        \node[above right] at (Ap) {$A'$};
    \fi
\end{tikzpicture}
